   comparison.innerHTML='<div class="tablewrap"><table><thead><tr><th>Product / order</th><th>Huidige kostprijs</th><th>Nettobedrag op deze factuur</th><th>Dekking</th></tr></thead><tbody>'+[...groups.values()].map(g=>{const o=context.order(g.orderId),item=o?.items.find(i=>i.id===g.itemId),other=(context.state.supplierInvoiceImports||[]).filter(r=>r.id!==old?.id).flatMap(r=>r.data.lines).filter(l=>l.orderId===g.orderId&&l.itemId===g.itemId).reduce((n,l)=>n+l.quantity,0);return '<tr><td>'+context.esc(item?.description||'Onbekend product')+' · #'+context.esc(o?.number||'?')+'</td><td>'+(item?.cost==null?(item?.purchaseCostTotal!=null?'Voorlopig · '+context.euro(item.purchaseCostTotal):'Nog onbekend'):context.euro(context.itemCostTotal(item)))+'</td><td>'+(g.known?context.euro(g.total):'Nog invullen')+'</td><td>'+context.esc(Number.isSafeInteger(g.quantity)&&g.quantity>0?g.quantity+other:'Nog invullen')+' / '+context.esc(item?.quantity||'?')+' fysieke stuks</td></tr>';}).join('')+'</tbody></table></div>';
   form.querySelector('[data-intake-existing-costs]').innerHTML=data.orderIds.map(id=>{const o=context.order(id),p=(context.state.purchases||[]).find(p=>p.id===o?.purchaseId),money=v=>v==null?'onbekend':context.euro(v);return '<p><strong>Order #'+context.esc(o?.number||'?')+'</strong> · eigen verzending '+money(o?.shippingActual)+' · overige vaste kosten '+money(o?.extraCosts)+' · overige benoemde kosten '+((o?.namedCosts||[]).filter(c=>!old||c.supplierInvoiceImportId!==old.id).some(c=>c.amount==null)?'Voorlopig · ':'')+money((o?.namedCosts||[]).filter(c=>!old||c.supplierInvoiceImportId!==old.id).reduce((n,c)=>n+(c.amount??0),0))+(p?' · zending '+context.esc(p.name)+' met transport '+money(p.freight)+' en overige kosten '+money(p.extraCosts):'')+'</p>';}).join('')||'<p>Kies eerst de betrokken orders.</p>';
