     if(button.hasAttribute('data-intake-report')){if(!await context.downloadBlob(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),'factuur-importverslag-'+context.today()+'.json'))throw Error('Importverslag kon niet worden gedownload.');status.textContent='Importverslag gedownload; er zijn geen kosten opgeslagen.';}
     else button.dispatchEvent(new CustomEvent('crm-invoice-import-feedback',{bubbles:true,detail:{target:button,report}}));return;
