      stage='pdf';const proof=await Promise.race([selectedProof(),cancelled]);if(!current())return;if(target)form.querySelector('[data-supplier-link-status]').textContent='Actieve factuurbron: '+(proof.document?.name||proof.blob.name||'Originele PDF');
      if(button.hasAttribute('data-intake-original')){if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(proof.blob);const panel=form.querySelector('[data-intake-original-panel]');panel.hidden=false;panel.innerHTML='<p><a target="_blank" rel="noopener" href="'+url+'">Origineel in eigen tab bekijken ↗</a></p><iframe title="Originele leveranciersfactuur" src="'+url+'" width="100%" height="400" sandbox="allow-same-origin"></iframe>';status.textContent='Bekijk het origineel en vergelijk alle bedragen en regels.';}
      else {const document=await Promise.race([readInvoicePdf(proof.blob,{signal:controller.signal,structured:true}),cancelled]);if(!current())return;const sourceHash=await proofHash(proof.blob);try{assertOrdinaryInvoiceText(document.text,{rows:document.rows});rememberProof(sourceHash,true);}catch(error){if(error.code==='invoice_document_kind')rememberProof(sourceHash,false);throw error;}layoutRows=document.rows;layoutText=document.text;form.querySelector('[data-intake-text]').value=document.text;log('pdf_ok');stage='proposal';recognize();}
