     const d=answer.data,allowed=Object.keys(blank());if(!d||typeof d!=='object'||Array.isArray(d)||Object.keys(d).some(k=>!allowed.includes(k))||d.currency!=='EUR'||!Array.isArray(d.lines)||d.lines.length>100||!Array.isArray(d.orderIds)||d.orderIds.length>100||!Array.isArray(d.supplierOrderReferences)||d.supplierOrderReferences.length>100)throw Error('Controleer JSON-velden, EUR, orders en maximaal 100 regels.');
     for(const k of ['reference','date','notes'])if(typeof d[k]!=='string'||d[k].length>(k==='notes'?6000:200))throw Error('Ongeldige tekstvelden in JSON.');
     for(const k of ['netCents','vatCents','grossCents','deductibleVatCents'])if(d[k]!==null&&(!Number.isSafeInteger(d[k])||d[k]<0||d[k]>1e12))throw Error('Gebruik gehele eurocenten of null voor onbekend.');
     if(d.deductibleVatCents!==null)throw Error('AI mag de aftrek niet kiezen. Gebruik null en vul de aftrek daarna zelf in.');
     if(d.supplierOrderReferences.some(v=>typeof v!=='string'||v.length>200)||d.orderIds.some(v=>typeof v!=='string'||!orders.some(o=>o.id===v))||!['equal','cost'].includes(d.allocation))throw Error('Onbekende order of ongeldige referentie/verdeling.');
